import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { LoadingController, ToastController, AlertController, IonRouterOutlet } from '@ionic/angular';
import { ICartFilterModel, CartFilterModel } from 'src/app/data/model/order/CartModel';
import { GAccount } from '../../../../../core/common/GAccount';
import { IUnSeenCourseQuestionsViewModel } from '../../../../../data/model/question/QuestionModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { ProductCartModel, ProductCartStatusViewModel, IProductCartModel } from '../../../../../data/model/order/ProductCartModel';
import { OrderService } from '../../../../../data/service/order/order.service';
import { ICartHistoryViewModel } from '../../../../../data/model/order/CartModel';

@Component({
  selector: 'app-orders',
  templateUrl: './orders.component.html',
  styleUrls: ['./orders.component.scss']
})
export class OrdersComponent implements OnInit {

  isSelected = false;
  isUnSeenLoading = true;
  login = false;
  unSeenQuestions: IUnSeenCourseQuestionsViewModel[] = [];
  courseSearch = '';
  selectedId = 0;
  selectedStatusCode = 0;
  price = 0;
  description = '';
  notfound = false;
  filteredCourses: ICartFilterModel = new CartFilterModel(false, 1, 12, '');
  selected: ICartHistoryViewModel;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
    private orderService: OrderService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    public alertController: AlertController,
    private fb: FormBuilder,
    public datepipe: DatePipe,
    public routerOutlet: IonRouterOutlet
  ) {

  }

  ngOnInit(): void {
  }

  onCheckStatus(p: IProductCartModel[]): string {

    let found = false;

    p.forEach(e => {

      if (e.statusCode != 100 && e.statusCode != 102) {
        found = true;
      }
    });

    if (found) {

      return 'نهایی نشده';
    } else {

      return 'نهایی شده';
    }
  }

  onGetSendType(id: number): string {

    switch (id) {
      case 1:

        return 'دریافت حضوری';
      case 2:

        return 'پیک موتوری';
      case 3:

        return 'تیپاکس';
      case 4:

        return 'پست';
      case 5:

        return 'پست پیشتاز';
      case 6:

        return 'باربری';
      case 7:

        return 'تیپاکس (پس کرایه)';

      default:
        return 'نوع ارسال غیر مجاز';
    }
  }

  onIsSeenCheck(c: ICartHistoryViewModel): boolean {

    let index = c.productCart.findIndex(e => !e.isSeen);

    return index == -1 ? false : true;
  }

  async presentAlertConfirm(id: number) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توجه',
      message: 'آیا مطمئن به تغییر وضعیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onChangeStatus(+id);
          }
        }
      ]
    });

    await alert.present();
  }

  onChangeSelect(statusCode) {

    this.selectedStatusCode = +statusCode.detail.value;

    this.price = 0;
    this.description = '';
  }

  onChangeStatus(id: number) {

    SharedIonic.loading(this.loadingController);

    const e = this.selected.productCart.find(x => x.id == id);

    this.orderService.ChangeProductCartStatus(
      new ProductCartStatusViewModel(
        id,
        this.selectedId,
        e.productId,
        e.designId == 0 ? e.productName : (e.productName + ' (' + e.designTitle + ')'),
        this.selectedStatusCode,
        this.description,
        this.price)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          if (this.filteredCourses.carts && this.filteredCourses.carts.length > 0) {

            this.filteredCourses.carts.forEach(cart => {
              const pcc = cart.productCart.find(x => x.id == id);

              if (pcc != undefined) {
                pcc.statusCode = this.selectedStatusCode;
                pcc.description = this.description;
              }
            });

            const pc = this.selected.productCart.find(x => x.id == id);
            pc.statusCode = this.selectedStatusCode;
            pc.description = this.description;
          } else {

            const pc = this.selected.productCart.find(x => x.id == id);
            pc.statusCode = this.selectedStatusCode;
            pc.description = this.description;
          }

          this.price = 0;
          this.description = '';

        } else if (res.status === GResponse.ErrorStatus) {

          SharedIonic.toast(this.toastController, 'انجام نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  ionViewWillEnter() {

    this.isSelected = false;

    this.login = GAccount.IsLoggedIn();

    let filter: ICartFilterModel;

    this.activatedRoute.params.subscribe(params => {

      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        this.isUnSeenLoading = true;
        this.unSeenQuestions = [];
        SharedIonic.loading(this.loadingController);

        this.isSelected = false;
        this.selectedId = 0;

        this.activatedRoute.queryParams.subscribe(queryParams => {

          SharedIonic.loading(this.loadingController);

          const page = queryParams.page;
          const take = queryParams.take ? queryParams.take : 12;
          const title = queryParams.title ? queryParams.title : '';
          const sortId = queryParams.sortId ? queryParams.sortId : 0;

          filter = new CartFilterModel(false, page, take, title, sortId);

          this.orderService.GetSellerCartByFilter(filter).subscribe(
            res => {
              if (res.status === GResponse.SuccessStatus) {
                this.filteredCourses = res.data;

                this.filteredCourses.carts.forEach(cart => {

                  cart.productCart.forEach(pc => {
                    if (pc.isDelete || cart.currentSellerId != pc.sellerId) {
                      let cartIndex = this.filteredCourses.carts.findIndex(e => e.id == cart.id);
                      let pcIndex = this.filteredCourses.carts[cartIndex].productCart.findIndex(e => e.id == pc.id);
                      this.filteredCourses.carts[cartIndex].productCart.splice(pcIndex, 1);
                    }
                  });
                });
                this.notfound = false;
                SharedIonic.dismissLoading(this.loadingController);

              } else if (res.status === GResponse.NotFoundStatus) {

                this.notfound = true;
                SharedIonic.toast(this.toastController, 'موردی یافت نشد');
                SharedIonic.dismissLoading(this.loadingController);
              }
            },
            err => {
              SharedIonic.dismissLoading(this.loadingController);
              SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
            }
          );
        });

        this.orderService.GetSellerUnSeenCartList().subscribe(
          res => {
            if (res.status === GResponse.SuccessStatus) {
              this.unSeenQuestions = res.data;
              this.isUnSeenLoading = false;

            } else if (res.status === GResponse.NotFoundStatus) {

              this.isUnSeenLoading = false;
              SharedIonic.toast(this.toastController, 'سفارش جدید ندارید');
            }
          },
          err => {
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      } else {

        SharedIonic.loading(this.loadingController);

        this.isSelected = false;
        this.selectedId = +id;

        this.orderService.GetSellerCartDetailById(this.selectedId).subscribe(
          res => {
            if (res.status === GResponse.SuccessStatus) {
              this.selected = res.data;

              this.selected.productCart.forEach(pc => {
                if (pc.isDelete || this.selected.currentSellerId != pc.sellerId) {
                  let pcIndex = this.selected.productCart.findIndex(e => e.id == pc.id);
                  this.selected.productCart.splice(pcIndex, 1);
                }
              });

              this.isSelected = true;
              SharedIonic.dismissLoading(this.loadingController);

            } else if (res.status === GResponse.NotFoundStatus) {

              SharedIonic.toast(this.toastController, 'سفارشی ثبت نشده است');
              SharedIonic.dismissLoading(this.loadingController);
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      }
    });
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();
      event.target.complete();
    }, 2000);
  }

  onSelect(index: number): void {

    this.selected = this.filteredCourses.carts[index];
    this.selectedId = this.selected.id;
    this.isSelected = true;

    let found = false;

    found = this.onIsSeenCheck(this.selected);

    if (found) {

      this.orderService.SetProductCartSeen(this.selectedId).subscribe(
        res => {
          if (res.status === GResponse.SuccessStatus) {

            this.selected.productCart.forEach(pc => {
              if (!pc.isSeen || this.selected.currentSellerId == pc.sellerId) {
                pc.isSeen = true;
              }

              this.unSeenQuestions.splice(this.unSeenQuestions.findIndex(e => e.courseId == this.selectedId), 1);
            });
          } else if (res.status === GResponse.NotFoundStatus) {

            SharedIonic.toast(this.toastController, 'سین ثبت نشد');
          }
        },
        err => {
          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      );
    }
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage2() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams2(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage2() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams2(+this.filteredCourses.pageId + 1);
    }
  }

  goPage2(pageId: number | string) {
    this.setQueryParams2(+pageId);
  }

  setQueryParams2(pageId: number) {

    const page = pageId < 1 ? 1 : pageId;

    const filter = new CartFilterModel
      (false, page, this.filteredCourses.takeEntity, this.courseSearch, this.filteredCourses.sortId);

    this.filteredCourses = filter;

    this.router
      .navigate(
        ['SellerPanel', 'Orders'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: filter.takeEntity ? filter.takeEntity : null,
            title: this.courseSearch,
            sortId: filter.sortId ? filter.sortId : 0
          }
        });
  }
}
